alter table public.webhook_integrations add column if not exists secret text; revoke select,insert,update,delete on public.webhook_integrations from authenticated,anon; grant select,insert,update on public.webhook_integrations to authenticated; create or replace function public.get_webhook_integration(p_endpoint_key text) returns table(id uuid,user_id uuid,funnel_id text,provider text,secret text,status text) language sql security definer set search_path=public as $$ select id,user_id,funnel_id,provider,secret,status from public.webhook_integrations where endpoint_key=p_endpoint_key and status='active' limit 1 $$; revoke execute on function public.get_webhook_integration(text) from public,anon,authenticated; grant execute on function public.get_webhook_integration(text) to service_role;